//! Native 3-stage DSpark stage discovery and quant contract, driven by the
//! pinned Vision-Exp tensor headers of BOTH packings.
//!
//! The fixture (`fixtures/vision-exp-tensor-headers.json`, regenerated by
//! `gen_tensor_header_fixture.py`) carries headers only — no payload — so these
//! tests are pure shape/dtype algebra and run on a host with no GPU.

use std::collections::{BTreeSet, HashMap};

use avarok_core::config::ModelConfig;
use spark_runtime::gpu::DevicePtr;
use spark_runtime::weights::{WeightDtype, WeightStore, WeightTensor};

use super::super::{check_native_dspark_checkpoint, discover_dspark_stages};

const FIXTURE: &str = include_str!("../fixtures/vision-exp-tensor-headers.json");

/// The packing keys in the fixture, in the order the bring-up doc lists them.
const PACKINGS: [&str; 2] = ["official", "nvfp4"];

fn dtype_of(name: &str) -> WeightDtype {
    match name {
        // safetensors spells the MXFP4 container I8 in the official packing and
        // U8 in the repack; the runtime maps both to UInt8 with no numerical
        // conversion (see the 0731 fixture README).
        "U8" | "I8" => WeightDtype::UInt8,
        "F8_E4M3" => WeightDtype::FP8E4M3,
        "F8_E8M0" => WeightDtype::FP8E8M0,
        "F32" => WeightDtype::FP32,
        "BF16" => WeightDtype::BF16,
        other => panic!("unexpected fixture dtype {other}"),
    }
}

/// Every tensor of one packing, as a `WeightStore` of null-pointer headers.
fn packing(key: &str) -> WeightStore {
    let doc: serde_json::Value = serde_json::from_str(FIXTURE).unwrap();
    let tensors = doc[key]["tensors"]
        .as_object()
        .unwrap_or_else(|| panic!("fixture has no `{key}.tensors`"));
    WeightStore::from_map(
        tensors
            .iter()
            .map(|(name, header)| {
                (
                    name.clone(),
                    WeightTensor {
                        ptr: DevicePtr::NULL,
                        shape: serde_json::from_value(header["shape"].clone()).unwrap(),
                        dtype: dtype_of(header["dtype"].as_str().unwrap()),
                    },
                )
            })
            .collect(),
    )
}

/// A store holding a subset of one packing, selected by name predicate.
fn packing_filtered(key: &str, keep: impl Fn(&str) -> bool) -> WeightStore {
    let full = packing(key);
    let names: Vec<String> = full.names().map(str::to_string).collect();
    let mut map: HashMap<String, WeightTensor> = HashMap::new();
    for name in names {
        if !keep(&name) {
            continue;
        }
        let t = full.get(&name).unwrap();
        map.insert(
            name.clone(),
            WeightTensor {
                ptr: t.ptr,
                shape: t.shape.clone(),
                dtype: t.dtype,
            },
        );
    }
    WeightStore::from_map(map)
}

/// The Vision-Exp geometry the fixture's headers belong to. Only the fields the
/// DSpark contract reads are set; nothing here is a default standing in for a
/// checkpoint value (PCND: every one of these is asserted against the fixture
/// by [`fixture_geometry_matches_the_contract_config`]).
fn vision_exp_config() -> ModelConfig {
    let mut config = ModelConfig::qwen3_next_80b_nvfp4();
    config.model_type = "deepseek_v4".into();
    config.num_hidden_layers = 43;
    config.hidden_size = 4096;
    config.vocab_size = 129280;
    config.num_experts = 256;
    config.moe_intermediate_size = 2048;
    config.shared_expert_intermediate_size = 2048;
    config.num_attention_heads = 64;
    config.q_lora_rank = 1024;
    config.kv_lora_rank = 512;
    config.hc_mult = 4;
    config.tp_rank = 0;
    config.tp_world_size = 1;
    config.ep_rank = 0;
    config.ep_world_size = 1;
    config.dspark_block_size = 5;
    config.dspark_noise_token_id = 128799;
    config.dspark_target_layer_ids = vec![40, 41, 42];
    config.dspark_markov_rank = 256;
    config
}

/// The fixture is sampled at experts 0 and 128, so a full 256-expert range
/// cannot be validated from it. Narrow the EP world to the sampled expert.
fn ep_of(config: &ModelConfig, expert: usize) -> ModelConfig {
    let mut c = config.clone();
    c.ep_world_size = 256;
    c.ep_rank = expert;
    c
}

#[test]
fn both_packings_discover_exactly_three_stages() {
    for key in PACKINGS {
        assert_eq!(
            discover_dspark_stages(&packing(key)),
            BTreeSet::from([0usize, 1, 2]),
            "{key}"
        );
    }
}

/// Stage-scoped tensors: `main_proj`/`main_norm` on stage 0 only, and the head
/// pieces (`norm`, `hc_head_*`, `markov_head`, `confidence_head`) on stage 2
/// only — the stages are ONE module split three ways, not three modules.
#[test]
fn stage_scoped_tensors_sit_where_the_contract_expects_them() {
    for key in PACKINGS {
        let store = packing(key);
        for (suffix, owner) in [
            ("main_proj.weight", 0usize),
            ("main_proj.scale", 0),
            ("main_norm.weight", 0),
            ("hc_head_fn", 2),
            ("hc_head_base", 2),
            ("hc_head_scale", 2),
            ("markov_head.markov_w1.weight", 2),
            ("markov_head.markov_w2.weight", 2),
            ("confidence_head.proj.weight", 2),
            // `forward_head` runs on `mtp[-1]`, and the checkpoint carries the
            // final norm only there.
            ("norm.weight", 2),
        ] {
            for stage in 0..3usize {
                let name = format!("mtp.{stage}.{suffix}");
                assert_eq!(
                    store.contains(&name),
                    stage == owner,
                    "{key}: {name} presence"
                );
            }
        }
        for stage in 0..3usize {
            for suffix in [
                "attn_norm.weight",
                "ffn_norm.weight",
                "attn.q_norm.weight",
                "attn.kv_norm.weight",
                "attn.attn_sink",
                "ffn.gate.weight",
                "ffn.gate.bias",
                // U2.3's per-modality routing bias: present on the stages too,
                // and inert there (every draft id is < vocab_size).
                "ffn.gate.bias_vl",
                "hc_attn_fn",
                "hc_ffn_fn",
            ] {
                let name = format!("mtp.{stage}.{suffix}");
                assert!(store.contains(&name), "{key}: {name} missing");
            }
        }
    }
}

/// The shapes the head reads are derived, not guessed: `main_proj` is
/// `[hidden, hidden * n_targets]`, the Markov tables are `[vocab, rank]` (NOT
/// `mtp_vocab_size` — C11), and the confidence projection is
/// `[1, hidden + rank]` with no bias tensor.
#[test]
fn head_tensor_geometry_is_derived_from_the_config() {
    let config = vision_exp_config();
    let h = config.hidden_size;
    let rank = config.dspark_markov_rank;
    for key in PACKINGS {
        let store = packing(key);
        assert_eq!(
            store.get("mtp.0.main_proj.weight").unwrap().shape,
            vec![h, h * config.dspark_target_layer_ids.len()],
            "{key}"
        );
        for table in ["markov_w1", "markov_w2"] {
            assert_eq!(
                store
                    .get(&format!("mtp.2.markov_head.{table}.weight"))
                    .unwrap()
                    .shape,
                vec![config.vocab_size, rank],
                "{key}: {table}"
            );
        }
        assert_eq!(
            store
                .get("mtp.2.confidence_head.proj.weight")
                .unwrap()
                .shape,
            vec![1, h + rank],
            "{key}"
        );
        assert!(
            !store.contains("mtp.2.confidence_head.proj.bias"),
            "{key}: DeepSeek's confidence head is Linear(.., 1, bias=False) — a bias \
             tensor here would mean the reference changed"
        );
        assert_eq!(
            store.get("mtp.2.hc_head_fn").unwrap().shape,
            vec![config.hc_mult, config.hc_mult * h],
            "{key}"
        );
    }
}

/// The fixture's own numbers, asserted against [`vision_exp_config`] so the
/// config above cannot drift away from the checkpoint it claims to describe.
#[test]
fn fixture_geometry_matches_the_contract_config() {
    let config = vision_exp_config();
    for key in PACKINGS {
        let store = packing(key);
        assert_eq!(
            store.get("mtp.0.attn.wq_a.weight").unwrap().shape,
            vec![config.q_lora_rank, config.hidden_size],
            "{key}"
        );
        assert_eq!(
            store.get("mtp.0.attn.kv_norm.weight").unwrap().shape,
            vec![config.kv_lora_rank],
            "{key}"
        );
        assert_eq!(
            store.get("mtp.0.attn.attn_sink").unwrap().shape,
            vec![config.num_attention_heads],
            "{key}"
        );
        assert_eq!(
            store.get("mtp.0.ffn.gate.weight").unwrap().shape,
            vec![config.num_experts, config.hidden_size],
            "{key}"
        );
    }
}

/// 🔴 The packings differ at the TARGET layers and agree at the DSpark stages.
/// A loader that inferred the draft expert format from the target's would be
/// wrong on the repack.
#[test]
fn both_packings_resolve_through_resolve_packed_expert() {
    use crate::weight_map::v4_quant::{PackedExpertFormat, resolve_packed_expert};
    let expected_target = [
        ("official", PackedExpertFormat::Mxfp4),
        ("nvfp4", PackedExpertFormat::Nvfp4),
    ];
    for (key, target_format) in expected_target {
        let store = packing(key);
        for expert in [0usize, 128] {
            for projection in ["w1", "w2", "w3"] {
                assert_eq!(
                    resolve_packed_expert(
                        &store,
                        &format!("layers.42.ffn.experts.{expert}.{projection}")
                    )
                    .unwrap(),
                    target_format,
                    "{key}: target layer expert {expert}.{projection}"
                );
                for stage in 0..3usize {
                    assert_eq!(
                        resolve_packed_expert(
                            &store,
                            &format!("mtp.{stage}.ffn.experts.{expert}.{projection}")
                        )
                        .unwrap(),
                        PackedExpertFormat::Mxfp4,
                        "{key}: stage {stage} expert {expert}.{projection}"
                    );
                }
            }
        }
    }
}

/// End-to-end: `check_native_dspark_checkpoint` with `use_speculative` accepts
/// both packings when the EP range is narrowed to a sampled expert.
#[test]
fn speculative_preflight_accepts_both_packings() {
    let base = vision_exp_config();
    for key in PACKINGS {
        // Only layer 42 is in the fixture, so validate a one-layer target whose
        // single layer IS layer 42's tensors.
        let store = packing_filtered(key, |n| {
            n.starts_with("mtp.") || n.starts_with("layers.42.")
        });
        let renamed = rename_layer_42_to_zero(&store);
        let mut config = ep_of(&base, 0);
        config.num_hidden_layers = 1;
        check_native_dspark_checkpoint(&renamed, &config, true)
            .unwrap_or_else(|e| panic!("{key}: {e:#}"));
    }
}

/// A store missing stage 1 must fail closed — never quietly draft with two.
#[test]
fn a_missing_stage_fails_closed() {
    let store = packing_filtered("official", |n| {
        (n.starts_with("mtp.") && !n.starts_with("mtp.1.")) || n.starts_with("layers.42.")
    });
    let renamed = rename_layer_42_to_zero(&store);
    let mut config = ep_of(&vision_exp_config(), 0);
    config.num_hidden_layers = 1;
    let err = check_native_dspark_checkpoint(&renamed, &config, true)
        .expect_err("a two-stage DSpark module must be refused");
    assert!(
        err.to_string().contains("requires stages {0,1,2}"),
        "got: {err:#}"
    );
}

/// A LEGACY single-module MTP checkpoint (`mtp.0.enorm`, no `main_proj`) takes
/// the legacy path: `--speculative` is accepted and the DSpark stage contract
/// is not applied.
#[test]
fn a_legacy_mtp_checkpoint_skips_the_dspark_contract() {
    let store = packing_filtered("official", |n| n.starts_with("layers.42."));
    let mut map: HashMap<String, WeightTensor> = store
        .names()
        .map(|n| {
            let t = store.get(n).unwrap();
            (
                n.replace("layers.42.", "layers.0."),
                WeightTensor {
                    ptr: t.ptr,
                    shape: t.shape.clone(),
                    dtype: t.dtype,
                },
            )
        })
        .collect();
    map.insert(
        "mtp.0.enorm.weight".into(),
        WeightTensor {
            ptr: DevicePtr::NULL,
            shape: vec![4096],
            dtype: WeightDtype::BF16,
        },
    );
    let mut config = ep_of(&vision_exp_config(), 0);
    config.num_hidden_layers = 1;
    check_native_dspark_checkpoint(&WeightStore::from_map(map), &config, true).unwrap();
}

fn rename_layer_42_to_zero(store: &WeightStore) -> WeightStore {
    WeightStore::from_map(
        store
            .names()
            .map(|n| {
                let t = store.get(n).unwrap();
                (
                    n.replace("layers.42.", "layers.0."),
                    WeightTensor {
                        ptr: t.ptr,
                        shape: t.shape.clone(),
                        dtype: t.dtype,
                    },
                )
            })
            .collect(),
    )
}
